import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { Polygon } from "@remotion/shapes";



export type AbstractDigitalTunnelProps = Record<string, any>;

const AbstractDigitalTunnel: React.FC<AbstractDigitalTunnelProps> = ({
  backgroundColor = "#03000a",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryColor = "#3A10E5",
  secondaryColor = "#00FFFF",
  shapePoints = 6,
  cornerRadius = 0,
  tunnelSpeed = 0.4,
  tunnelDepth = 24,
  twistAmount = 180,
  rotationSpeed = 0.05,
  glowIntensity = 20,
  strokeThickness = 3,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const time = frame / fps;
  const minDim = Math.min(width, height);
  const baseRadius = minDim / 4;

  const centerGlowTransparent = `${primaryColor}00`;
  const centerGlowColor = `${primaryColor}66`;

  // Create an array of shape data representing depths in the tunnel
  const shapes = Array.from({ length: tunnelDepth }).map((_, i) => {
    const offset = (i / tunnelDepth) + (time * tunnelSpeed);
    const rawProgress = offset % 1; // Loops from 0 (deep center) to 1 (at the camera)
    return { i, rawProgress };
  });

  // Sort strictly by rawProgress ascending to ensure proper Z-ordering (furthest elements rendered first)
  shapes.sort((a, b) => a.rawProgress - b.rawProgress);

  const centerGlowOpacity = interpolate(
    Math.sin(time * Math.PI * 2 * 0.5),
    [-1, 1],
    [0.5, 1]
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      
      {/* Central Ethereal Glow */}
      {!transparentBackground && (
        <div
          style={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            width: minDim * 0.6,
            height: minDim * 0.6,
            transform: 'translate(-50%, -50%)',
            background: `radial-gradient(circle, ${centerGlowColor} 0%, ${centerGlowTransparent} 70%)`,
            filter: 'blur(30px)',
            transition: 'none',
            opacity: centerGlowOpacity,
            zIndex: 1,
            pointerEvents: 'none',
          }}
        />
      )}

      {/* Tunnel Layers */}
      {shapes.map(({ i, rawProgress }) => {
        // Accelerating scale to simulate true 3D perspective projection
        const scale = interpolate(
          rawProgress,
          [0, 1],
          [0.01, 15],
          { easing: Easing.in(Easing.poly(3)) }
        );

        // Fade in gracefully at the center and fade out sharply right before clipping the camera
        const baseOpacity = interpolate(
          rawProgress,
          [0, 0.1, 0.8, 1],
          [0, 1, 1, 0],
          { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
        );

        // Rhythmic pulsing alternating per shape layer
        const pulse = interpolate(
          Math.sin((time * Math.PI * 2) + (i * 0.5)),
          [-1, 1],
          [0.3, 1]
        );

        // Smooth twisting motion combined with constant continuous rotation
        const rotation = (rawProgress * twistAmount) + (time * rotationSpeed * 360);
        
        // Cinematic depth of field: blurry at the distant center and extreme close-up, sharp in the middle
        const blurAmount = interpolate(
          rawProgress,
          [0, 0.15, 0.5, 0.85, 1],
          [4, 1, 0, 1, 8],
          { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
        );

        const isCyan = i % 2 === 0;
        const color = isCyan ? secondaryColor : primaryColor;

        return (
          <div
            key={i}
            style={{
              position: 'absolute',
              top: '50%',
              left: '50%',
              width: minDim,
              height: minDim,
              transform: `translate(-50%, -50%) scale(${scale}) rotate(${rotation}deg)`,
              opacity: baseOpacity * pulse,
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              transition: 'none',
              filter: `blur(${blurAmount}px)`,
              zIndex: 10,
            }}
          >
            <Polygon
              points={shapePoints}
              radius={baseRadius}
              fill="transparent"
              stroke={color}
              strokeWidth={strokeThickness}
              cornerRadius={cornerRadius}
              style={{
                filter: glowIntensity > 0 ? `drop-shadow(0px 0px ${glowIntensity}px ${color})` : 'none',
                transition: 'none',
                overflow: 'visible',
              }}
            />
          </div>
        );
      })}

      {/* Cinematic Vignette Overlay */}
      {!transparentBackground && (
        <div
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            background: 'radial-gradient(circle, transparent 40%, rgba(0,0,0,0.8) 100%)',
            pointerEvents: 'none',
            transition: 'none',
            zIndex: 20,
          }}
        />
      )}
    </AbsoluteFill>
  );
};

export default AbstractDigitalTunnel;